import React, { useMemo, useCallback, memo } from 'react';

interface Citation {
  id: string;
  documentTitle: string;
  excerpt: string;
}

interface CitationListProps {
  citations: Citation[];
  onCitationClick: (id: string) => void;
}

// memo: Only re-renders when citations array reference or onCitationClick reference changes
const CitationList = memo(function CitationList({ citations, onCitationClick }: CitationListProps) {
  console.log('CitationList rendered');
  return (
    <ul role="list" className="space-y-2">
      {citations.map((citation) => (
        <li key={citation.id} className="p-2 border border-border rounded">
          <button
            type="button"
            onClick={() => onCitationClick(citation.id)}
            className="text-left text-accent-fg hover:underline"
          >
            {citation.documentTitle}
          </button>
          <p className="text-xs text-fg-muted mt-1 italic">"{citation.excerpt}"</p>
        </li>
      ))}
    </ul>
  );
});

// Parent component: stabilize references so CitationList never re-renders during token streaming
function ChatResponseView({ streamingContent, rawCitations }: { streamingContent: string; rawCitations: Citation[] }) {
  // Stable: only recomputes when rawCitations array changes
  const sortedCitations = useMemo(
    () => [...rawCitations].sort((a, b) => a.documentTitle.localeCompare(b.documentTitle)),
    [rawCitations]
  );

  // Stable: only changes when the outer handler dependency changes
  const handleCitationClick = useCallback((id: string) => {
    console.log('Citation selected:', id);
  }, []); // No deps = stable for the entire session

  return (
    <div>
      <p className="text-fg-default">{streamingContent}</p>
      <CitationList citations={sortedCitations} onCitationClick={handleCitationClick} />
    </div>
  );
}

import { useRef } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
}

export function VirtualizedMessageList({ messages }: { messages: Message[] }) {
  const parentRef = useRef<HTMLDivElement>(null);

  const virtualizer = useVirtualizer({
    count: messages.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 120, // Estimated average row height in px
    overscan: 5, // Render 5 extra items above/below viewport for smooth scrolling
  });

  return (
    <div ref={parentRef} className="h-full overflow-y-auto">
      {/* Full virtual height container - prevents scroll position jumps */}
      <div style={{ height: `${virtualizer.getTotalSize()}px`, position: 'relative' }}>
        {virtualizer.getVirtualItems().map((virtualItem) => {
          const message = messages[virtualItem.index];
          return (
            <div
              key={virtualItem.key}
              data-index={virtualItem.index}
              ref={virtualizer.measureElement} // Dynamic height measurement
              style={{ position: 'absolute', top: `${virtualItem.start}px`, left: 0, right: 0 }}
              className={`p-4 ${message.role === 'user' ? 'bg-canvas-subtle' : 'bg-canvas-default'}`}
            >
              <MessageBubble message={message} />
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { lazy, Suspense } from 'react';

// Lazy loaded: imported chunk only downloaded when first rendered
const MermaidRenderer = lazy(() => import('./MermaidRenderer'));

function DiagramBlock({ code }: { code: string }) {
  return (
    <Suspense
      fallback={
        <div className="h-40 bg-canvas-subtle animate-pulse rounded flex items-center justify-center">
          <span className="text-fg-muted text-sm">Loading diagram...</span>
        </div>
      }
    >
      <MermaidRenderer code={code} />
    </Suspense>
  );
}
